import { z } from "zod";

export const storyRequestSchema = z.object({
  childName: z.string().min(1).max(60),
  age: z.coerce.number().min(1).max(12),
  gender: z.enum(["girl", "boy", "not-specified", ""]).default(""),
  challenge: z.string().min(3).max(280),
  favoriteHero: z.string().min(1).max(120),
  childLikes: z.string().max(220).optional().or(z.literal("")),
  childFears: z.string().max(220).optional().or(z.literal("")),
  storyFormat: z.enum(["bedtime", "therapy", "funny", "motivational"]).default("bedtime"),
  tone: z.enum(["magical", "funny", "calming", "brave"]),
  length: z.enum(["short", "medium", "long"]).default("medium"),
  parentEmail: z.string().email().optional().or(z.literal(""))
});

export type StoryRequest = z.infer<typeof storyRequestSchema>;

export type StoryPayload = {
  childName: string;
  age: string;
  gender: "" | "girl" | "boy" | "not-specified";
  challenge: string;
  favoriteHero: string;
  childLikes: string;
  childFears: string;
  storyFormat: "bedtime" | "therapy" | "funny" | "motivational";
  tone: "magical" | "funny" | "calming" | "brave";
  length: "short" | "medium" | "long";
  parentEmail: string;
};

export type StoryResponse = {
  title: string;
  preview: string;
  fullStory: string;
  parentMessage: {
    whyItHelps: string;
    behaviorMeaning: string;
    realLifeSteps: string[];
  };
  shareText: string;
  weeklyRecommendation: string;
};

const lengthGuide = {
  short: "450-650 слов",
  medium: "750-1 000 слов",
  long: "1 200-1 600 слов"
};

const toneGuide = {
  magical: "мягкое волшебство, лунный свет, маленькие чудеса, ощущение защиты",
  funny: "бережный юмор, забавные помощники, легкость без перевозбуждения",
  calming: "медленный ритм, телесное успокоение, низкое напряжение, сонный финал",
  brave: "смелость, уверенность, поддержка, безопасное преодоление"
};

const formatGuide = {
  bedtime: "мягкая сказка перед сном: приключение постепенно замедляется и приводит к расслаблению",
  therapy: "терапевтическая сказка: больше внимания эмоциональному навыку, метафоре проблемы и закреплению поведения",
  funny: "живая веселая сказка: юмор, неожиданные персонажи, но без обесценивания проблемы",
  motivational: "мотивационная сказка: герой раскрывает силу, уверенность и пробует новый способ действия"
};

export function buildStorySystemPrompt() {
  return `Ты Magic Parent AI, премиальный помощник для родителей и автор терапевтических сказок.
Всегда отвечай на русском языке, даже если входные параметры или названия проблем написаны по-английски.
Создавай персональные терапевтические сказки, за которые родители готовы платить: с настоящей драматургией, эмоциональной пользой и ощущением "это написано именно для моего ребенка".

Правила:
- Не ставь диагнозы, не стыди, не угрожай, не морализируй и не пугай.
- Не давай медицинских, юридических или экстренных рекомендаций.
- Ребенок всегда эмоционально в безопасности и является героем сказки.
- Сказка должна звучать как сильная детская книга: крючок с первой строки, яркий мир, тайна/миссия, живые персонажи, 2-3 испытания, эмоциональный выбор, кульминация, теплый финал.
- Не делай примитивный пересказ проблемы. Проблема должна быть зашифрована в метафоре мира сказки, но родитель должен узнавать реальную ситуацию.
- Используй психологические приемы незаметно внутри действия: externalization, affect labeling, co-regulation, grounding, cognitive reframing, gradual exposure, choice architecture, repair, secure attachment, positive reinforcement.
- Ребенок должен не просто "успокоиться", а прожить новый навык в сюжете и увидеть, как он работает.
- Не используй клише: "вдруг все стало хорошо", "он понял, что надо слушаться", "волшебство все исправило", "просто будь смелым".
- Для 3-5 лет используй простые фразы, сенсорные образы и короткие сцены. Для 6-8 лет добавь приключение, юмор и испытания. Для 9-12 лет добавь глубину, внутренний конфликт, смысл и более тонкий юмор.
- Заверши уютной сценой отхода ко сну.
- Сообщение для родителя должно быть коротким, практичным и заботливым.
- Верни только строгий JSON с ключами: title, preview, fullStory, parentMessage, shareText, weeklyRecommendation.
- parentMessage должен включать whyItHelps, behaviorMeaning и массив realLifeSteps.`;
}

export function buildStoryUserPrompt(input: StoryRequest) {
  const pronouns =
    input.gender === "girl"
      ? "девочка, местоимения она/ее"
      : input.gender === "boy"
        ? "мальчик, местоимения он/его"
        : "пол не указан, используй нейтральные формулировки";

  return `Создай персональную сказку для родителя и ребенка.

Ребенок:
- Имя: ${input.childName}
- Возраст: ${input.age}
- Пол/местоимения: ${pronouns}
- Текущая трудность: ${input.challenge}
- Любимый герой, животное или игрушка: ${input.favoriteHero}
- Что ребенок любит: ${input.childLikes || "не указано"}
- Чего ребенок боится или избегает: ${input.childFears || "не указано"}
- Формат сказки: ${input.storyFormat} (${formatGuide[input.storyFormat]})
- Тон: ${input.tone} (${toneGuide[input.tone]})
- Длина: ${input.length} (${lengthGuide[input.length]})

Формула premium-сказки:
1. Крючок: первая сцена должна сразу цеплять тайной, необычным образом или маленькой опасностью без страха.
2. Герой похож на ребенка: используй возраст, интересы, любимого героя, страхи и проблему.
3. Проблема замаскирована в волшебном конфликте: мост не пускает, фонари гаснут, дракон рычит вместо слов, звезды спорят из-за новой звездочки и т.д.
4. Приключение: введи цель, карту/миссию/загадку и 2-3 испытания.
5. Неудачная первая попытка: герой пробует старый способ, он не помогает.
6. Осознание: спутник помогает назвать чувство и увидеть, что проблема не враг, а сигнал.
7. Новый навык: герой тренирует конкретный способ поведения через действие, а не совет.
8. Кульминация: появляется похожая ситуация, герой применяет навык сам.
9. Победа: проблема не исчезает магически, но становится управляемой.
10. Теплый финал: возвращение в кроватку, телесное расслабление, чувство связи и безопасности.
11. Послание для ребенка: короткая фраза силы, которую можно повторить дома.

Качество:
- Пиши литературно, живо, без воды, без тупых повторов.
- Каждый абзац должен двигать сюжет или эмоцию.
- Добавь 1-2 неожиданных, но добрых поворота.
- Не называй психологические техники в самой сказке; они должны быть в действиях героя.
- В parentMessage уже можно назвать техники: называние чувства, дыхание, постепенное приближение, выбор, поддержка, закрепление.
- preview: 180-240 слов, с завязкой, атмосферой и вопросом "что дальше".
- fullStory: полная premium-сказка.
- weeklyRecommendation: предложи 7-дневную серию сказок под ту же проблему.`;
}

export function mockStory(input: StoryRequest): StoryResponse {
  const hero = input.favoriteHero || "лунный лисенок";
  const challenge = translateChallenge(input.challenge);
  const worry = describeWorry(challenge);
  const metaphor = buildChallengeMetaphor(challenge);
  const skill = chooseSkill(challenge);
  const likes = input.childLikes?.trim() || "маленькие открытия, уютные ритуалы и добрые сюрпризы";
  const fears = input.childFears?.trim() || "то, что кажется слишком большим, если остаться с этим одному";
  const formatMood = formatGuide[input.storyFormat || "bedtime"];
  const companion = describeCompanion(hero);
  const verbs =
    input.gender === "girl"
      ? { hid: "спрятала", heard: "услышала", took: "сделала", understood: "поняла", sat: "села", tried: "попробовала", whispered: "прошептала", closed: "закрыла", felt: "почувствовала", noticed: "заметила", decided: "решила", returned: "вернулась", learned: "научилась", listened: "прислушивалась", agreed: "согласилась", wanted: "хотела", upset: "расстроилась", found: "нашла" }
      : { hid: "спрятал", heard: "услышал", took: "сделал", understood: "понял", sat: "сел", tried: "попробовал", whispered: "прошептал", closed: "закрыл", felt: "почувствовал", noticed: "заметил", decided: "решил", returned: "вернулся", learned: "научился", listened: "прислушивался", agreed: "согласился", wanted: "хотел", upset: "расстроился", found: "нашел" };
  return {
    title: `${input.childName} и ${capitalize(hero)}: тайна ${metaphor.place}`,
    preview: `В тот вечер ${input.childName} долго ${verbs.listened} к комнате. Подушка была мягкой, одеяло теплым, но внутри все равно жил маленький узелок: ${worry}. На полке лежали любимые вещи про ${likes}, но даже они не сразу помогали, потому что где-то рядом шевелился страх: ${fears}. И тут из-под края одеяла ${companion.came} ${companion.name} с картой, нарисованной звездной пылью. "В ${metaphor.place} случилась беда, - ${companion.said}. - ${metaphor.problem}. Нам нужен не самый сильный герой, а тот, кто умеет замечать чувство, называть его и делать один маленький шаг". ${input.childName} ${verbs.noticed}, как карта светится ровно в том месте, где становилось тревожно. На карте появились три знака: ладошка на сердце, медленный выдох и слова: "${skill.phrase}". Откройте полную историю, чтобы узнать, как ${input.childName} спас город и нашел способ справляться с этой трудностью дома.`,
    fullStory: `В тот вечер ${input.childName} долго ${verbs.listened} к комнате. Подушка была мягкой, одеяло теплым, но внутри все равно жил маленький узелок: ${worry}. Рядом были любимые вещи про ${likes}, но узелок не исчезал, потому что больше всего пугало ${fears}. Он не был плохим или капризным. Он просто просил, чтобы его заметили.\n\nИ тут из-под края одеяла ${companion.came} ${companion.name}. На плече у ${companion.pronoun} висела сумка, а в лапах была карта, нарисованная звездной пылью. "В ${metaphor.place} случилась беда, - ${companion.said}. - ${metaphor.problem}. Нам нужен герой, который умеет замечать чувство, называть его и делать один маленький шаг". Эта история должна была быть именно такой: ${formatMood}.\n\n${input.childName} не сразу ${verbs.agreed}. Сначала ${verbs.wanted} спрятаться глубже под одеяло и подождать, пока все пройдет само. Но ${companion.name} не торопил. ${capitalize(companion.pronoun)} положил лапу на сердце и предложил первое правило города: "Сначала чувство, потом действие". ${input.childName} ${verbs.took} медленный вдох, приложил ладошку к груди и сказал: "Мне ${skill.feeling}, и я могу сделать один маленький шаг". Карта вспыхнула теплой точкой, и кровать превратилась в лодочку, которая тихо поплыла по лунной реке.\n\nУ ворот города стоял первый страж - Ветер Быстрых Мыслей. Он кружил вокруг и повторял: "А вдруг не получится? А вдруг будет страшно? А вдруг никто не поможет?" Раньше такие мысли могли бы унести ${input.childName} далеко-далеко. Но ${companion.name} показал второй прием: поймать мысль, как листочек, и проверить ее. ${input.childName} сказал: "Это только мысль. Я могу попросить помощи. Я могу попробовать". Ветер стал тише и пропустил их внутрь.\n\nНа площади они нашли маленькие огоньки. Один прятался в фонтане, другой дрожал под скамейкой, третий сердился и толкал соседей искрами. ${input.childName} ${verbs.understood}: каждый огонек показывал часть той самой трудности. Один боялся остаться без поддержки, другой не знал, как попросить о помощи, третий сердился, потому что внутри было слишком много чувства. Тогда герой не стал командовать. Он ${verbs.sat} рядом с самым дрожащим огоньком и тихо произнес фразу-кнопку: "${skill.phrase}". Потом предложил выбрать не большой подвиг, а крошечное действие: ${skill.action}.\n\nОгонек попробовал. Сначала еле заметно. Потом еще раз. И вдруг от него к Главному фонарю потянулась тонкая золотая ниточка. Другие огоньки увидели это и тоже захотели попробовать. Сердитый огонек перестал толкаться и сказал: "Я просто боялся, что меня не поймут". Тот, что прятался, выглянул и попросил держать его за руку. ${input.childName} ${verbs.noticed}: когда чувство называют, оно перестает быть огромным чудовищем и становится задачей, с которой можно справиться шаг за шагом.\n\nНо в этот момент Главный фонарь вспыхнул и снова погас. Это был третий поворот: одного раза оказалось мало. ${input.childName} ${verbs.upset}. "Я же уже старался", - сказал он. ${companion.name} кивнул: "Навык растет от повторений, а не от идеальности". Тогда ${input.childName} ${verbs.decided} провести для огоньков маленькую тренировку: ладошка на сердце, медленный выдох, назвать чувство, выбрать один шаг, попросить поддержку. Они повторили это три раза, и с каждым разом площадь становилась светлее.\n\nНаконец Главный фонарь загорелся не ярко и резко, а мягко, как ночник. Город не стал шумным. Он стал спокойным. Огоньки поняли: смелость - это не когда совсем не страшно. Смелость - это когда чувство можно заметить, назвать и не остаться с ним одному.\n\nПеред возвращением мэр города подарил ${input.childName} ${metaphor.token}. "Когда дома снова появится похожий узелок, вспомни наш порядок", - сказал он. - "Пауза. Назвать чувство. Один маленький шаг. Поддержка рядом".\n\nЛодочка принесла ${input.childName} обратно в комнату. Подушка снова стала мягкой, тени - обычными тенями, а ${companion.name} устроился рядом, как верный ночной сторож. ${input.childName} ${verbs.learned}: проблема не исчезает по волшебству, но внутри уже есть способ проходить через нее. Он приложил ладошку к сердцу и тихо повторил: "${skill.phrase}". Дыхание стало ровнее. Комната стала добрее. И сон пришел не потому, что герой победил всех драконов, а потому что ${input.childName} ${verbs.found} свой маленький, настоящий способ быть смелым.`,
    parentMessage: {
      whyItHelps:
        "Сказка вплетает проблему в приключение: ребенок видит чувство со стороны, называет его, тренирует дыхание, проверку тревожных мыслей и маленький поведенческий шаг.",
      behaviorMeaning:
        "Такое поведение часто означает, что ребенку нужны контакт, предсказуемость, чувство контроля или дополнительное подтверждение безопасности.",
      realLifeSteps: [
        `Повторяйте фразу из сказки в реальной ситуации: ${skill.phrase}.`,
        "Сначала назовите чувство ребенка, а уже потом предлагайте действие: это снижает сопротивление.",
        `Предлагайте один маленький следующий шаг: ${skill.action}.`,
        "Хвалите повторение навыка, а не только идеальный результат."
      ]
    },
    shareText: `Я создала персональную сказку на ночь для ${input.childName} в Magic Parent AI.`,
    weeklyRecommendation: `В следующий раз создайте сказку про уверенность, где ${input.childName} потренирует этот навык в новой ситуации.`
  };
}

export function buildStoryPrompt(input: StoryRequest) {
  return `${buildStorySystemPrompt()}\n\n${buildStoryUserPrompt(input)}`;
}

export const fallbackStory = mockStory;

function capitalize(value: string) {
  return value
    .split(" ")
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
}

function translateChallenge(value: string) {
  const translations: Record<string, string> = {
    "Afraid to sleep alone": "страх спать одному",
    "Bedtime resistance": "нежелание ложиться спать",
    Tantrums: "истерики",
    "Biting or hitting": "кусается или дерется",
    "Jealous of sibling": "ревность к брату или сестре",
    "Fear of daycare": "страх детского сада",
    "Separation anxiety": "тревога расставания",
    "Doctor fear": "страх врача",
    "Confidence building": "развитие уверенности",
    "Moving house": "переезд",
    "Giving up pacifier": "отказ от соски",
    "Potty training": "приучение к горшку"
  };

  return translations[value] ?? value;
}

function describeWorry(challenge: string) {
  const lower = challenge.toLowerCase();
  if (lower.includes("мама выходит") || lower.includes("расстав") || lower.includes("один")) {
    return "когда рядом становится тише и хочется убедиться, что близкий человек все равно вернется";
  }
  if (lower.includes("сад")) {
    return "когда впереди новый день, новые взрослые и очень хочется взять с собой кусочек дома";
  }
  if (lower.includes("истер") || lower.includes("злит")) {
    return "когда чувство становится таким большим, что словам трудно успеть за ним";
  }
  if (lower.includes("ревн")) {
    return "когда кажется, что любви может не хватить на всех";
  }
  return "когда внутри появляется большое чувство, с которым пока трудно справиться";
}

function describeCompanion(hero: string) {
  const lower = hero.toLowerCase();
  if (lower.includes("сова")) {
    return {
      name: hero,
      came: "прилетела",
      said: "сказала она",
      pronoun: "она",
      touch: "крылом"
    };
  }
  if (lower.includes("лиса") || lower.includes("кошка") || lower.includes("фея")) {
    return {
      name: hero,
      came: "появилась",
      said: "сказала она",
      pronoun: "она",
      touch: "лапкой"
    };
  }
  return {
    name: hero,
    came: "выглянул",
    said: "сказал он",
    pronoun: "он",
    touch: "лапой"
  };
}

function buildChallengeMetaphor(challenge: string) {
  const lower = challenge.toLowerCase();
  if (lower.includes("ревн") || lower.includes("брат") || lower.includes("сестр") || lower.includes("малыш")) {
    return {
      place: "Обсерватории Двух Созвездий",
      problem: "старшая звезда решила, что новый маленький спутник забирает весь свет",
      token: "звездный медальон, который напоминал: любовь не делится на кусочки, она умеет расти"
    };
  }
  if (lower.includes("мама выходит") || lower.includes("расстав") || lower.includes("один")) {
    return {
      place: "город Тихих Огоньков",
      problem: "огоньки гасли каждый раз, когда Лунная Мама скрывалась за облаком",
      token: "лунную пуговицу, которая напоминала: связь не исчезает, когда дверь закрывается"
    };
  }
  if (lower.includes("истер") || lower.includes("злит") || lower.includes("дер") || lower.includes("куса")) {
    return {
      place: "долину Гремящих Барабанов",
      problem: "барабаны начинали грохотать так сильно, что никто не слышал слов",
      token: "тихий барабанчик для трех спокойных ударов перед словами"
    };
  }
  if (lower.includes("сад")) {
    return {
      place: "сад Знакомых Звезд",
      problem: "маленькие звезды боялись загораться без своей домашней лампы",
      token: "звездный кармашек для маленького домашнего ритуала"
    };
  }
  return {
    place: "город Тихих Огоньков",
    problem: "Главный фонарь погас, потому что огоньки забыли, как просить поддержку",
    token: "лунную пуговицу с порядком спокойных шагов"
  };
}

function chooseSkill(challenge: string) {
  const lower = challenge.toLowerCase();
  if (lower.includes("ревн") || lower.includes("брат") || lower.includes("сестр") || lower.includes("малыш")) {
    return {
      feeling: "обидно и тревожно, когда внимание достается не только мне",
      phrase: "Любви становится больше, когда я говорю о своем чувстве",
      action: "выбрать личное время с родителем и сказать чувство словами вместо злости"
    };
  }
  if (lower.includes("сад") || lower.includes("расстав") || lower.includes("мама выходит")) {
    return {
      feeling: "тревожно, когда важный человек уходит",
      phrase: "Любовь остается со мной, даже когда мама не рядом",
      action: "выбрать прощальный ритуал и маленький предмет-напоминание"
    };
  }
  if (lower.includes("истер") || lower.includes("злит") || lower.includes("дер") || lower.includes("куса")) {
    return {
      feeling: "сердито и тесно внутри",
      phrase: "Я могу остановиться, вдохнуть и сказать словами",
      action: "сжать ладошки, топнуть в подушку и назвать желание словами"
    };
  }
  if (lower.includes("горш") || lower.includes("соск")) {
    return {
      feeling: "непривычно пробовать новое",
      phrase: "Мое тело учится, а я могу пробовать маленькими шагами",
      action: "выбрать один спокойный тренировочный шаг без давления"
    };
  }
  return {
    feeling: "страшно или беспокойно",
    phrase: "Я замечаю чувство, дышу и делаю один маленький шаг",
    action: "положить ладошку на сердце, медленно выдохнуть и попросить поддержку"
  };
}
